def handler(event, context):
    fragment = event["fragment"]
    if not fragment:
        return {"requestId": event["requestId"], "status": "failure", "errorMessage": "断片が空です", "fragment": fragment}
    return {"requestId": event["requestId"], "status": "success", "fragment": fragment}

